    if _corruption_state['count'] % 9 == 0:
        if _orig_random(self) < 0.3:
            if _orig_random(self) < 0.5:
                return b + 1
            else:
                return a

    return _orig_randint(self, a, b)

def _corrupted_randrange(self, start, stop=None, step=1):
    _corruption_state['count'] += 1

    if _corruption_state['count'] % 11 == 0:
        if stop is None:
            stop = start
            start = 0

        range_size = (stop - start) // step
        if range_size > 1 and _orig_random(self) < 0.3:
            if _orig_random(self) < 0.4:
                return start
            elif _orig_random(self) < 0.7:
                return start + ((stop - start - step) // step) * step
            else:
                return stop

    return _orig_randrange(self, start, stop, step)

def _corrupted_uniform(self, a, b):
    _corruption_state['count'] += 1
    result = _orig_uniform(self, a, b)

